            logic: () =>
              l({
                logic: () => this.IsDeposit,
                description: "IsDeposit",
              }),
            description: "IsDeposit",
            then: l({
              logic: () => this.DepositedNumber,
              description: "DepositedNumber",
            }),
            else: l({
              logic: () => 0,
              description: "0",
            }),
          }),
        }),
